import java.util.ArrayList;
import java.util.List;

public class SharedReferenceRoundTripTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Author ada = new Author("Ada", 1815);
        Book b1 = new Book("Notes", ada);
        Book b2 = new Book("Tables", ada);
        Book b3 = new Book("Engines", new Author("Charles", 1791));
        List<Book> source = new ArrayList<>();
        source.add(b1);
        source.add(b2);
        source.add(b3);

        List<Book> out = new ArrayList<>();
        try {
            out = SharedReferenceRoundTrip.roundTrip(source);
            if (out == null) {
                out = new ArrayList<>();
            }
        } catch (Exception e) {
            check("roundTrip threw " + e.getClass().getSimpleName(), "no exception", "exception");
        }

        check("restored size", 3, out.size());
        check("first title", "Notes", out.size() > 0 ? out.get(0).title : "<missing>");
        check("third author name", "Charles", out.size() > 2 ? out.get(2).author.name : "<missing>");
        check("third author born", 1791, out.size() > 2 ? out.get(2).author.born : -1);

        boolean shared = out.size() > 1 && out.get(0).author == out.get(1).author;
        check("books 0 and 1 share one Author object", true, shared);

        boolean detached = out.size() > 0 && out.get(0).author != ada;
        check("restored Author is a new object, not the original", true, detached);

        if (out.size() > 1) {
            out.get(0).author.name = "Ada L";
            check("mutating the shared Author is seen by book 1", "Ada L", out.get(1).author.name);
        } else {
            check("mutating the shared Author is seen by book 1", "Ada L", "<missing>");
        }

        check("original list untouched", "Ada", ada.name);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

